#include <cstdio>
#include <vector>
#include "../.local/nvidia-audit/cpp/2_Concepts_and_Techniques/sortingNetworks/oddEvenMergeSort.cu"
template<class T> void save(const char*path,const T*data,size_t n){FILE*f=fopen(path,"wb");if(!f||fwrite(data,sizeof(T),n,f)!=n){fprintf(stderr,"Capture write failed\n");exit(1);}fclose(f);}
int main(){const unsigned N=1048576;std::vector<unsigned> input(N),values(N),keys(N),outvalues(N);srand(2001);for(unsigned i=0;i<N;i++){input[i]=rand()%65536;values[i]=i;}save("reports/odd-even-input-keys.bin",input.data(),N);unsigned *ik,*iv,*ok,*ov;checkCudaErrors(cudaMalloc(&ik,N*4));checkCudaErrors(cudaMalloc(&iv,N*4));checkCudaErrors(cudaMalloc(&ok,N*4));checkCudaErrors(cudaMalloc(&ov,N*4));checkCudaErrors(cudaMemcpy(ik,input.data(),N*4,cudaMemcpyHostToDevice));checkCudaErrors(cudaMemcpy(iv,values.data(),N*4,cudaMemcpyHostToDevice));
for(unsigned dir=0;dir<2;dir++)for(unsigned length=64;length<=N;length*=2){oddEvenMergeSort(ok,ov,ik,iv,N/length,length,dir);checkCudaErrors(cudaDeviceSynchronize());checkCudaErrors(cudaMemcpy(keys.data(),ok,N*4,cudaMemcpyDeviceToHost));checkCudaErrors(cudaMemcpy(outvalues.data(),ov,N*4,cudaMemcpyDeviceToHost));for(unsigned i=0;i<N;i++){if(outvalues[i]>=N||keys[i]!=input[outvalues[i]]||(i%length&&((dir&&keys[i-1]>keys[i])||(!dir&&keys[i-1]<keys[i])))){fprintf(stderr,"Validation failed\n");return 1;}}char path[180];snprintf(path,sizeof(path),".local/odd-even-captures/%u-%u-keys.bin",dir,length);save(path,keys.data(),N);snprintf(path,sizeof(path),".local/odd-even-captures/%u-%u-values.bin",dir,length);save(path,outvalues.data(),N);printf("dir %u length %u total %u passed\n",dir,length,N);}
checkCudaErrors(cudaFree(ik));checkCudaErrors(cudaFree(iv));checkCudaErrors(cudaFree(ok));checkCudaErrors(cudaFree(ov));}
